def _render(image_bytes, params):
    from io import BytesIO
    from PIL import Image, ImageDraw, ImageFont
    title, greeting = params.get('title') or '', params.get('greeting') or ''
    position = params.get('text_position', 'top')
    if not isinstance(title, str) or not isinstance(greeting, str):
        raise ValueError('invalid_text')
    if not title and not greeting:
        return image_bytes
    if position not in ('top', 'bottom'):
        raise ValueError('invalid_text_position')
    font_bytes = zlib.decompress(base64.b64decode(FONT_DATA))
    if hashlib.sha256(font_bytes).hexdigest() != FONT_SHA256:
        raise ValueError('invalid_font')
    image = Image.open(BytesIO(image_bytes)).convert('RGB')
    w, h = image.size
    if w * 4 != h * 3:
        raise ValueError('invalid_aspect_ratio')
    draw = ImageDraw.Draw(image)
    lines = []
    for kind, text, ratio in [('title', title, .082), ('greeting', greeting, .042)]:
        font = ImageFont.truetype(BytesIO(font_bytes), round(w * ratio))
        wrapped = []
        for paragraph in text.split('\n'):
            line = ''
            for word in paragraph.split(' '):
                candidate = line + (' ' if line else '') + word
                if font.getlength(candidate) <= w * .87:
                    line = candidate
                else:
                    if not line or font.getlength(word) > w * .87:
                        raise ValueError('text_overflow')
                    wrapped.append(line)
                    line = word
            if line:
                wrapped.append(line)
        if len(wrapped) > 3:
            raise ValueError('text_overflow')
        for line in wrapped:
            box = font.getbbox(line)
            lines.append((kind, line, font, box, box[3] - box[1]))
    gap = round(w * .009)
    block_gap = round(w * .02) if title and greeting else 0
    total = sum(x[4] for x in lines) + gap * max(0, len(lines)-1) + block_gap
    top, bottom = (round(h * .035), round(h * .32)) if position == 'top' else (round(h * .68), round(h * .965))
    if total > bottom - top:
        raise ValueError('text_overflow')
    y, previous = top + (bottom - top - total)//2, None
    for kind, line, font, box, height in lines:
        if previous == 'title' and kind == 'greeting':
            y += block_gap
        x = round((w - (box[2] - box[0])) / 2 - box[0])
        draw.text((x, y-box[1]), line, font=font, fill='#243d4a')
        y += height + gap
        previous = kind
    output = BytesIO()
    image.save(output, format='JPEG', quality=95, subsampling=0)
    return output.getvalue()


def _result(**values):
    return json.dumps(dict(version=VERSION, **values), ensure_ascii=False)


def handle(data):
    """Return JSON; never echo credentials, signed URLs, or image contents."""
    try:
        params = json.loads(data) if isinstance(data, str) else data
        if not isinstance(params, dict):
            return _result(ok=False, error="invalid_parameters")
        action = params.get("action", "inspect")
        if action == 'send_status':
            response = params.get('response')
            if isinstance(response, str):
                try:
                    response = json.loads(response)
                except ValueError:
                    response = {}
            response = response if isinstance(response, dict) else {}
            message = response.get('message') or {}
            message = message if isinstance(message, dict) else {}
            body = message.get('body') or {}
            recipient = message.get('recipient') or {}
            mid = body.get('mid') if isinstance(body, dict) else None
            attachments = body.get('attachments', []) if isinstance(body, dict) else []
            valid = (isinstance(mid, str) and bool(mid) and isinstance(recipient, dict)
                and str(recipient.get('chat_id')) == str(params.get('expected_chat_id'))
                and isinstance(attachments, list)
                and any(isinstance(a, dict) and a.get('type') == 'image' for a in attachments))
            return _result(ok=bool(valid), status='delivered' if valid else 'delivery_error',
                mid=mid if valid else '',
                notice='Открытка отправлена. Для следующей напишите «Начать заново».' if valid else
                    'Отправка не завершилась. Напишите «Повторить отправку». Повторная генерация не запускается.')
        if action == 'pack_order':
            fields = ('occasion', 'recipient', 'caption_mode', 'caption_text', 'title_mode',
                      'title_text', 'greeting_mode', 'greeting_text')
            order = {key: params.get(key) or '' for key in fields}
            if any(not isinstance(v, str) or len(v) > 2000 for v in order.values()):
                return _result(ok=False, error='invalid_order')
            # A complete JSON string literal, safe as an unquoted API-body substitution.
            return _result(ok=True, user_content_json=json.dumps(json.dumps(order, ensure_ascii=False), ensure_ascii=False))
        if action == 'parse_plan':
            try:
                plan = json.loads(params.get('content', ''))
                if not isinstance(plan, dict):
                    raise ValueError()
                for key in ('concept', 'title', 'greeting', 'image_prompt', 'text_position'):
                    if not isinstance(plan.get(key), str):
                        raise ValueError()
                if not 20 <= len(plan['image_prompt']) <= 16000 or plan['text_position'] not in ('top', 'bottom', 'none'):
                    raise ValueError()
                if plan.get('needs_shorter_text') or len(plan['title']) > 180 or len(plan['greeting']) > 300:
                    return _result(ok=False, error='text_overflow')
                request = {'model':'gpt-image-2.5-flare', 'prompt':plan['image_prompt'],
                    'size':'1152x1536', 'quality':'low', 'output_format':'jpeg', 'n':1}
                return _result(ok=True, stage='plan_review', concept=plan['concept'], title=plan['title'], greeting=plan['greeting'],
                    text_position=plan['text_position'], image_request_json=json.dumps(request, ensure_ascii=False))
            except (ValueError, TypeError):
                return _result(ok=False, error='invalid_plan')
        if action == 'probe':
            try:
                from PIL import Image, ImageFont
                return _result(ok=True, pillow=True)
            except ImportError:
                return _result(ok=False, error='pillow_unavailable')
        if action not in ("inspect", "upload", "render_upload"):
            return _result(ok=False, error="invalid_action")
        encoded = params.get("image_b64")
        if not isinstance(encoded, str) or not encoded:
            return _result(ok=False, error="missing_image_b64")
        if len(encoded) > ((MAX_BYTES + 2) // 3) * 4:
            return _result(ok=False, error="image_too_large")
        try:
            image = base64.b64decode(encoded, validate=True)
        except (ValueError, binascii.Error):
            return _result(ok=False, error="invalid_base64")
        if not image.startswith(b"\xff\xd8\xff") or not image.endswith(b"\xff\xd9"):
            return _result(ok=False, error="not_jpeg")
        if action == 'render_upload':
            try:
                image = _render(image, params)
            except ImportError:
                return _result(ok=False, error='pillow_unavailable')
            except ValueError as error:
                safe_errors = {'invalid_text', 'invalid_text_position', 'invalid_font', 'invalid_aspect_ratio', 'text_overflow'}
                return _result(ok=False, error=str(error) if str(error) in safe_errors else 'render_error')
        info = dict(byte_length=len(image), sha256=hashlib.sha256(image).hexdigest(),
                    mime_type="image/jpeg")
        if action == 'render_upload':
            info['font_sha256'] = FONT_SHA256
        if action == "inspect":
            return _result(ok=True, **info)

        upload_url = params.get("upload_url")
        if not isinstance(upload_url, str):
            return _result(ok=False, error="missing_upload_url")
        parts = urlsplit(upload_url)
        if (parts.scheme != "https" or parts.hostname != "iu.oneme.ru"
                or parts.port not in (None, 443) or parts.path != "/uploadImage"
                or parts.username or parts.password or parts.fragment):
            return _result(ok=False, error="invalid_max_upload_url")
        headers = {"Accept": "application/json"}
        token = params.get("max_token")
        if token:
            if not isinstance(token, str) or "\r" in token or "\n" in token:
                return _result(ok=False, error="invalid_authorization")
            headers["Authorization"] = token
        try:
            response = requests.post(upload_url, headers=headers,
                files={"data": ("postcard.jpg", image, "image/jpeg")},
                timeout=(2, 8), allow_redirects=False)
        except requests.exceptions.Timeout:
            return _result(ok=False, error="upload_timeout")
        except requests.exceptions.RequestException:
            return _result(ok=False, error="upload_network_error")
        if not 200 <= response.status_code < 300:
            return _result(ok=False, error="upload_http_error", http_status=response.status_code)
        try:
            body = response.json()
        except ValueError:
            return _result(ok=False, error="upload_invalid_json")
        photos = body.get("photos", {}) if isinstance(body, dict) else {}
        photo_tokens = [entry["token"] for entry in photos.values()
                        if isinstance(entry, dict) and isinstance(entry.get("token"), str)
                        and entry["token"]] if isinstance(photos, dict) else []
        if len(photo_tokens) != 1:
            return _result(ok=False, error="upload_missing_image_token")
        return _result(ok=True, attachment={"type": "image", "payload": {"token": photo_tokens[0]}}, **info)
    except (TypeError, ValueError, KeyError):
        return _result(ok=False, error="invalid_parameters")
    except Exception:
        return _result(ok=False, error="handler_error")
